import React, { useState } from "react";
import { Modal, Button } from "react-bootstrap";

export default function ProjectsSection({ bg, textColor, height }) {
  const [selectedProject, setSelectedProject] = useState(null);

  const projects = [
    {
      id: 1,
      title: "Transcendence",
      image: "/transcendence-screen1.png",
      description:
        "Application Web d'un jeu pong en réseau via le framework Django avec création et gestion de compte, tchat et plusieurs modes de jeu",
    },
    {
      id: 2,
      title: "Minishell",
      image: "/minishell-screen1.png",
      description:
        "Implementation d'un invité de commande simplifié avec variables d'environnement, builtins, redirections et heredoc",
    },
    {
      id: 3,
      title: "Cube3D",
      image: "/cube3D-screen1.png",
      description:
        "Implementation de l'algorithme de raycasting en langage C avec textures et parsing selon certaines règles des maps",
    },
    {
      id: 4,
      title: "Portfolio",
      image: "/portfolio-screen1.png",
      description:
        "Site Web présentant mes principaux projets étudiants et personnels via React et Bootstrap",
    },
    {
      id: 5,
      title: "Projet 5",
      image: "/project.jpg",
      description: "Description du projet 5.",
    },
    {
      id: 6,
      title: "Projet 6",
      image: "/project.jpg",
      description: "Description du projet 6.",
    },
  ];

  return (
    <section
      id="projets"
      className={`${bg} ${textColor}`}
      style={{
        scrollMarginTop: `${height}px`,
        backgroundImage: "url('/bg-projects.jpg')",
        backgroundRepeat: "no-repeat",
        backgroundPosition: "top",
        backgroundSize: "cover",
        width: "100%",
        padding: "4rem 1rem", // top/bottom et responsive padding horizontal
        boxSizing: "border-box",
      }}
    >
      <h2 className="text-center mb-5">Mes Projets</h2>

      <div className="container">
        <div className="row gx-4 gy-4">
          {projects.map((project) => (
            <div
              key={project.id}
              className="col-12 col-sm-6 col-md-4 d-flex"
              onClick={() => setSelectedProject(project)}
              style={{ cursor: "pointer" }}
            >
              <div className="card shadow-sm w-100">
                <img
                  src={project.image}
                  alt={project.title}
                  className="card-img-top"
                  style={{ objectFit: "cover", height: "200px" }}
                />
                <div className="card-body text-center">
                  <h5 className="card-title">{project.title}</h5>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Modal pour afficher le projet sélectionné */}
      <Modal
        show={!!selectedProject}
        onHide={() => setSelectedProject(null)}
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>{selectedProject?.title}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <img
            src={selectedProject?.image}
            alt={selectedProject?.title}
            className="img-fluid rounded mb-3"
          />
          <p>{selectedProject?.description}</p>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setSelectedProject(null)}>
            Fermer
          </Button>
        </Modal.Footer>
      </Modal>
    </section>
  );
}
